def _safe_name(name: str) -> tuple[str, str, str]:
    clean = " ".join(name.strip().split())
    if not clean or len(clean) > 64 or any(c in clean for c in '<>:\\"/|?*'):
        raise ValueError("Project name must be 1-64 characters and contain no path or reserved filename characters.")
    slug = "".join(c.lower() if c.isalnum() else "-" for c in clean).strip("-")
    package = "_".join("".join(c.lower() if c.isalnum() else "_" for c in clean).split())
    if not package or package[0].isdigit(): package = "project_" + package
    return clean, slug or "eva-project", package

def scaffold(template: str, target: str | Path, name: str) -> dict:
    """Create a new project only; refuses existing/non-empty targets and path traversal."""
    if template not in TEMPLATES:
        raise ValueError(f"Unknown template {template!r}. Available: {', '.join(sorted(TEMPLATES))}")
    clean, slug, package = _safe_name(name)
    dest = Path(target).expanduser().resolve()
    if dest.exists():
        if not dest.is_dir() or any(dest.iterdir()):
            raise FileExistsError("Target already exists and is not empty; EVA never overwrites a project scaffold.")
    else:
        dest.mkdir(parents=True, exist_ok=False)
    mapping = {"name": clean, "slug": slug, "package": package, "description": f"{clean} command-line application"}
    written = []
    try:
        for raw_path, raw_content in TEMPLATES[template].items():
            rel = raw_path.replace("{package}", package)
            out = (dest / rel).resolve()
            if dest not in out.parents:
                raise ValueError("Template path escaped target directory.")
            out.parent.mkdir(parents=True, exist_ok=True)
            content = raw_content
            for key, value in mapping.items():
                content = content.replace("{" + key + "}", str(value))
            content = content.replace("{description!r}", repr(mapping["description"]))
            out.write_text(content, encoding="utf-8", newline="\n")
            written.append(rel)
        manifest = {"template": template, "name": clean, "files": written, "generated_by": "EVA deterministic scaffold", "verification": "not yet validated"}
        (dest / ".eva-project.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        written.append(".eva-project.json")
    except Exception:
        # Remove only files created by this invocation, not pre-existing data.
        for rel in reversed(written):
            try: (dest / rel).unlink()
            except OSError: pass
        raise
    return {"status": "created", "template": template, "name": clean, "target": str(dest), "files": written,
            "next_steps": ["Review generated files", "Run EVA validation", "Run project tests in a reviewed environment"]}

def available_templates() -> list[dict[str, str]]:
    return [{"id": key, "description": {"python-cli": "Python package with CLI and a smoke test", "java-console": "Java console application", "web-static": "Professional responsive HTML/CSS/JS website with design system"}[key]} for key in sorted(TEMPLATES)]
